package com.hms.dao;
import com.hms.model.Appointment; import java.sql.*; import java.time.*; import java.util.*;
public class AppointmentDao {
 private final Connection c; public AppointmentDao(Connection c){this.c=c;}
 public List<Appointment> find(String q)throws SQLException{List<Appointment>x=new ArrayList<>();String s="SELECT a.*,p.name patient_name,d.name doctor_name FROM appointments a JOIN patients p ON p.id=a.patient_id JOIN doctors d ON d.id=a.doctor_id WHERE p.name LIKE ? OR d.name LIKE ? OR a.status LIKE ? ORDER BY a.appointment_date DESC,a.start_time";try(PreparedStatement p=c.prepareStatement(s)){String v="%"+(q==null?"":q.trim())+"%";for(int i=1;i<4;i++)p.setString(i,v);try(ResultSet r=p.executeQuery()){while(r.next())x.add(new Appointment(r.getInt("id"),r.getInt("patient_id"),r.getString("patient_name"),r.getInt("doctor_id"),r.getString("doctor_name"),r.getDate("appointment_date").toLocalDate(),r.getTime("start_time").toLocalTime(),r.getTime("end_time").toLocalTime(),r.getString("status"),r.getString("notes")));}}return x;}
 public List<Appointment> findRecent()throws SQLException{return find("");}
 public void save(Appointment a)throws SQLException{validateDate(a);ensureAvailable(a,0);String s="INSERT INTO appointments(patient_id,doctor_id,appointment_date,start_time,end_time,status,notes) VALUES(?,?,?,?,?,?,?)";try(PreparedStatement p=c.prepareStatement(s)){set(p,a);p.executeUpdate();}}
 public void update(Appointment a)throws SQLException{validateDate(a);ensureAvailable(a,a.id());String s="UPDATE appointments SET patient_id=?,doctor_id=?,appointment_date=?,start_time=?,end_time=?,status=?,notes=? WHERE id=?";try(PreparedStatement p=c.prepareStatement(s)){set(p,a);p.setInt(8,a.id());p.executeUpdate();}}
 private void set(PreparedStatement p,Appointment a)throws SQLException{p.setInt(1,a.patientId());p.setInt(2,a.doctorId());p.setDate(3,java.sql.Date.valueOf(a.date()));p.setTime(4,Time.valueOf(a.startTime()));p.setTime(5,Time.valueOf(a.endTime()));p.setString(6,a.status());p.setString(7,a.notes());}
 public void delete(int id)throws SQLException{try(PreparedStatement p=c.prepareStatement("DELETE FROM appointments WHERE id=?")){p.setInt(1,id);p.executeUpdate();}}
 public int count(String status)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM appointments WHERE status=?")){p.setString(1,status);try(ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}}
 public List<Appointment> todayAndUpcoming() throws SQLException { return findByFilters(LocalDate.now(), null, null, null); }
 public List<Appointment> findByFilters(LocalDate from, LocalDate to, String status, Integer doctorId) throws SQLException {
  List<Appointment> out=new ArrayList<>(); String sql="SELECT a.*,p.name patient_name,d.name doctor_name FROM appointments a JOIN patients p ON p.id=a.patient_id JOIN doctors d ON d.id=a.doctor_id WHERE (? IS NULL OR a.appointment_date>=?) AND (? IS NULL OR a.appointment_date<=?) AND (? IS NULL OR a.status=?) AND (? IS NULL OR a.doctor_id=?) ORDER BY a.appointment_date,a.start_time";
  try(PreparedStatement p=c.prepareStatement(sql)){p.setDate(1,from==null?null:java.sql.Date.valueOf(from));p.setDate(2,from==null?null:java.sql.Date.valueOf(from));p.setDate(3,to==null?null:java.sql.Date.valueOf(to));p.setDate(4,to==null?null:java.sql.Date.valueOf(to));p.setString(5,status);p.setString(6,status);if(doctorId==null){p.setNull(7,Types.INTEGER);p.setNull(8,Types.INTEGER);}else{p.setInt(7,doctorId);p.setInt(8,doctorId);}try(ResultSet r=p.executeQuery()){while(r.next())out.add(new Appointment(r.getInt("id"),r.getInt("patient_id"),r.getString("patient_name"),r.getInt("doctor_id"),r.getString("doctor_name"),r.getDate("appointment_date").toLocalDate(),r.getTime("start_time").toLocalTime(),r.getTime("end_time").toLocalTime(),r.getString("status"),r.getString("notes")));}}return out;
 }
 private void validateDate(Appointment a){if(a.date().isBefore(LocalDate.now()))throw new IllegalArgumentException("Past appointment dates are not allowed.");}
 private void ensureAvailable(Appointment a,int id)throws SQLException{if("CANCELLED".equals(a.status()))return;String q="SELECT COUNT(*) FROM appointments WHERE doctor_id=? AND appointment_date=? AND start_time=? AND status<>'CANCELLED' AND id<>?";try(PreparedStatement p=c.prepareStatement(q)){p.setInt(1,a.doctorId());p.setDate(2,java.sql.Date.valueOf(a.date()));p.setTime(3,Time.valueOf(a.startTime()));p.setInt(4,id);try(ResultSet r=p.executeQuery()){r.next();if(r.getInt(1)>0)throw new IllegalArgumentException("Doctor already has an active appointment at this time.");}}}
}
